import bpy, math
# move sign group left + up so chef hat (centre) is clear
for o in bpy.data.objects:
    if o.name.startswith(("SignBoard","SignFace","SignRAMEN","SignSub","SignOcto","SignHanger")):
        o.location.x -= 0.95; o.location.z += 0.18
r = bpy.data.objects.get("SignRAMEN");
if r: r.location.z += 0.05
s = bpy.data.objects.get("SignSub");
if s: s.location.z += 0.04
# inner lanterns outward
for o in bpy.data.objects:
    if o.name.startswith("Lantern2"): o.location.x -= 0.55
    if o.name.startswith("Lantern3"): o.location.x += 0.55
# lift octopus core a touch
core_prefixes = ("Octo","Spot","EyeWhite","Pupil","Highlight","Brow","Mouth","Tongue","Cheek","Hat","Bandana","Apron")
for o in bpy.data.objects:
    if o.name.startswith(core_prefixes):
        o.location.z += 0.08
m = bpy.data.objects.get("Mouth")
if m: m.scale = (0.85,0.85,0.85)
# punchier colour if available
vs = bpy.context.scene.view_settings
try:
    looks = [i.identifier for i in vs.bl_rna.properties['look'].enum_items]
    if 'Punchy' in looks: vs.look = 'Punchy'
    look_used = vs.look
except Exception as e:
    look_used = f"err {e}"
result = {"ok": True, "look": look_used, "hatband_z": bpy.data.objects["HatBand"].location.z}

import bpy, builtins
H = builtins._H; look_at = H['look_at']
# remove centre noren panel -> window for chef; remove sign hangers (antennae)
for o in list(bpy.data.objects):
    if o.name in ("Noren2","NorenCircle2","NorenDot2") or o.name.startswith("SignHanger"):
        bpy.data.objects.remove(o, do_unlink=True)
# chef a bit more forward
core_prefixes = ("Octo","Spot","EyeWhite","Pupil","Highlight","Brow","Mouth","Tongue","Cheek","Hat","Bandana","Apron")
for o in bpy.data.objects:
    if o.name.startswith(core_prefixes):
        o.location.y -= 0.12
# inner lanterns slightly lower so they don't cover sign sub-text
for o in bpy.data.objects:
    if o.name.startswith(("Lantern2","Lantern3")):
        o.location.z -= 0.18
# lower hero camera to see under eave
cam = bpy.data.objects["Camera"]
cam.location = (4.3, -6.7, 2.65)
look_at(cam, (0, 0.3, 1.55))
result = {"ok": True, "objects": len(bpy.data.objects)}

import bpy
from mathutils import Vector
hits = []
for o in bpy.data.objects:
    if o.type != 'MESH': continue
    try:
        corners = [o.matrix_world @ Vector(c) for c in o.bound_box]
    except: continue
    xs=[c.x for c in corners]; ys=[c.y for c in corners]; zs=[c.z for c in corners]
    # region in front of / at forehead: x -0.85..0.85, y -0.25..0.45, z 2.40..2.90
    if max(xs)>-0.85 and min(xs)<0.85 and max(ys)>-0.25 and min(ys)<0.45 and max(zs)>2.40 and min(zs)<2.90:
        hits.append((o.name, [round(v,2) for v in (min(xs),max(xs),min(ys),max(ys),min(zs),max(zs))]))
result = {"hits": hits}
